export type VimshopakaVarga = {
	varga: Varga,
	/**  Varga burcu. */
	sign: Sign,
	/**  Basamak: `OwnSign`, `GreatFriend`, `Friend`, `Neutral`, `Enemy` ya da `GreatEnemy`. */
	relation: Dignity,
	/**  Basamağın değeri: 20, 18, 15, 10, 7 ya da 5. */
	points: number | null,
};

/**  Pencerenin başındaki beş uzuv ve lagna burcu. */
export type WindowSnapshot = {
	vara: Vara,
	tithi: number,
	paksha: Paksha,
	nakshatra: number,
	pada: number,
	yoga: number,
	karana: number,
	karana_name: KaranaName,
	lagna_sign: Sign,
};

/**  Yılın lagnaya bağlı olguları; doğum saati bilinmiyorsa hiçbiri verilmez (K2). */
export type YearFacts = {
	/**  Yıllık haritanın lagna burcu ve lordu. */
	lagna_sign: Sign,
	lagna_lord: Graha,
	/**  Doğum haritasının lagna burcu ve lordu. */
	natal_lagna_sign: Sign,
	natal_lagna_lord: Graha,
	muntha: Muntha,
};

export type YogaGroup = "Mahapurusha" | "Lunar" | "Solar" | "Raja" | "Dhana" | "Exchange" | "ViparitaRaja" | "NeechaBhanga" | "NabhasaCount" | "NabhasaAshraya" | "Dosha";

/**  Oluşan bir yoga: bir kuralın bir eşleşmesi. */
export type YogaHit = {
	/**  Kararlı kimlik (`"mahapurusha.hamsa"`); görünen ad i18n anahtarıdır. */
	id: string,
	group: YogaGroup,
	/**  Yogayı oluşturan grahalar, `Graha::ALL` sırasında. */
	grahas: Graha[],
	/**  Lagnadan sayılan ilgili evler, artan sırada; doğum saati bilinmiyorsa boş. */
	houses: number[],
	/**  İki grahanın ilişkisine dayanan kurallarda ilişki türleri; diğerlerinde boş. */
	relations: YogaRelation[],
	/**  Sağlanan alt koşul kimlikleri (`YOGA_CONDITIONS`); alt koşulu olmayan kurallarda boş. */
	conditions: string[],
	/**
	 *  Doğum saati bilinmiyor: konumlar yaklaşıktır (Ay'ın burcu gün içinde değişebilir) ve
	 *  lagnaya bağlı seçenekler değerlendirilmemiştir.
	 */
	approximate: boolean,
};

/**
 *  İki grahanın ilişkisi (spec §8 "ilişkili"). v1'deki `dignity::Relation` (doğal dostluk)
 *  başka bir kavramdır.
 */
export type YogaRelation = 
/**  Aynı burç. */
"Conjunction" | 
/**  İki grahanın birbirine burç temelli tam bakışı. */
"MutualAspect" | 
/**  İki grahanın birbirinin burcunda olması (parivartana). */
"Exchange";

/**  `compute_yogas` sonucu. */
export type YogaReport = {
	catalog_version: number,
	/**  Katalog sırasıyla; bir kuralın birden çok eşleşmesi graha sırasıyla. */
	hits: YogaHit[],
	/**  Değerlendirilen kural sayısı. */
	evaluated: number,
	/**  Doğum saati bilinmediği için değerlendirilmeyen (lagna isteyen) kural sayısı. */
	skipped_time_unknown: number,
};

/**  Yogi noktası ve ondan okunan üç graha. */
export type YogiFacts = {
	/**  Yogi noktasının sidereal boylamı, [0, 360). */
	point_lon: number | null,
	/**  Noktanın rasi çerçevesindeki burcu (K5). */
	sign: Sign,
	/**  Rasi çerçevesinde burç içi derece, [0, 30). */
	deg_in_sign: number | null,
	/**  Noktanın nakshatrası, 1..=27 (sidereal). */
	nakshatra: number,
	/**  1..=4. */
	pada: number,
	/**  Noktanın nakshatra lordu. */
	yogi: Graha,
	/**  Eş yogi: noktanın burcunun lordu. */
	co_yogi: Graha,
	/**  Yogi nakshatrasından altıncı nakshatra, 1..=27. */
	avayogi_nakshatra: number,
	/**  O nakshatranın lordu. */
	avayogi: Graha,
};

export type ZodiacMode = 
/**  Burç, nakshatra ve evler sidereal boylamdan. */
"Sidereal" | 
/**  Burç, burç içi derece ve evler tropikal boylamdan; nakshatra ve pada sidereal boylamdan. */
"TropicalRasiSiderealNakshatra";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}
